// Token Launch Radar dashboard — no network, no libraries.
// Data comes from ../data.js (generated by `node main.ts`); if that file
// is missing it falls back to a fetch of ../board.json.
// Hash routing (so screenshots can target a state):
//   #protocol=<slug>   open that protocol's detail view
//   #cat=<category>    filter the board to a category
//   #chain=<chain>     filter the board to a chain
(function () {
  "use strict";

  var $ = function (id) { return document.getElementById(id); };
  var esc = function (s) {
    return String(s).replace(/[&<>"']/g, function (c) {
      return { "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c];
    });
  };
  var fmtMoney = function (usd) {
    if (usd >= 1e9) return "$" + (usd / 1e9).toFixed(2) + "B";
    if (usd >= 1e6) return "$" + (usd / 1e6).toFixed(usd >= 1e8 ? 0 : 1) + "M";
    if (usd >= 1e3) return "$" + (usd / 1e3).toFixed(1) + "K";
    return "$" + Math.round(usd);
  };
  var fmtPct = function (x, digits) {
    var v = x * 100;
    return (v > 0 ? "+" : "") + v.toFixed(digits == null ? 0 : digits) + "%";
  };
  var fmtNum = function (x) { return x.toLocaleString("en-US"); };

  function loadBoard() {
    if (window.TOKEN_RADAR_BOARD && window.TOKEN_RADAR_BOARD.rows) {
      return Promise.resolve(window.TOKEN_RADAR_BOARD);
    }
    return fetch("../board.json").then(function (r) { return r.json(); });
  }

  function verdictClass(v) { return v === "LONG SHOT" ? "LONG" : v; }

  function stateFromHash() {
    var h = location.hash.replace(/^#/, "");
    var out = {};
    h.split("&").forEach(function (part) {
      var kv = part.split("=");
      if (kv.length === 2) out[decodeURIComponent(kv[0])] = decodeURIComponent(kv[1]);
    });
    return out;
  }

  function main(data) {
    var meta = data.meta;
    var rows = data.rows.slice();

    $("stat-rows").textContent = fmtNum(meta.rows) + " protocols";
    $("stat-fdv").textContent = fmtMoney(meta.totalImpliedFdvUsd) + " implied FDV";
    $("stat-ev").textContent = fmtMoney(meta.totalFarmerEvUsd) + " farmer EV";
    $("provenance-text").textContent =
      "Source: " + meta.source + ". Snapshot: " + meta.snapshotDate +
      ". " + fmtNum(meta.rows) + " pre-token protocols, " +
      fmtMoney(meta.totalTvlUsd) + " TVL, global peer multiple " + meta.globalMultiple + "×.";
    $("foot-meta").textContent =
      "Generated " + meta.generatedAt.slice(0, 10) + " · " + meta.source;

    // ---- filter controls ----
    var cats = [...new Set(rows.map(function (r) { return r.category; }))].sort();
    var chains = [...new Set(rows.flatMap(function (r) { return r.chains; }))].sort();
    cats.forEach(function (c) {
      var o = document.createElement("option"); o.value = c; o.textContent = c; $("cat").appendChild(o);
    });
    chains.forEach(function (c) {
      var o = document.createElement("option"); o.value = c; o.textContent = c; $("chain").appendChild(o);
    });

    // ---- charts (top 10 by radar score, whatever the table sorts by) ----
    renderTop10(rows.slice().sort(function (a, b) { return b.radarScore - a.radarScore; }).slice(0, 10));
    renderMultiples(meta.categoryMultiples);
    renderScatter(rows);

    var activeSlug = null;

    function applyFilters() {
      var q = $("q").value.trim().toLowerCase();
      var cat = $("cat").value;
      var chain = $("chain").value;
      var sort = $("sort").value;
      var ptsOnly = $("points-only").checked;
      var primeOnly = $("prime-only").checked;
      var list = rows.filter(function (r) {
        if (q && (r.name + " " + r.slug + " " + r.category).toLowerCase().indexOf(q) === -1) return false;
        if (cat && r.category !== cat) return false;
        if (chain && r.chains.indexOf(chain) === -1) return false;
        if (ptsOnly && !r.points) return false;
        if (primeOnly && r.verdict !== "PRIME") return false;
        return true;
      });
      var key = { radar: "radarScore", fdv: "impliedFdvUsd", tvl: "tvlUsd", growth: "tvlGrowth7d", ev: "farmerEvUsd", odds: "launchProbability" }[sort];
      list.sort(function (a, b) { return b[key] - a[key]; });
      renderTable(list);
      $("count").textContent = fmtNum(list.length) + " of " + fmtNum(rows.length) + " shown";
      return list;
    }

    function renderTable(list) {
      var tb = $("board-body");
      tb.innerHTML = "";
      $("empty").hidden = list.length > 0;
      list.forEach(function (r) {
        var tr = document.createElement("tr");
        tr.dataset.slug = r.slug;
        if (r.slug === activeSlug) tr.className = "active";
        var barCls = r.radarScore >= 70 ? "" : r.radarScore >= 50 ? "low" : "vlow";
        tr.innerHTML =
          "<td>" + r.rank + "</td>" +
          '<td><span class="name">' + esc(r.name) + "</span>" +
          (r.points ? ' <span class="sub">· ' + esc(r.pointsProgram || "points") + "</span>" : "") + "</td>" +
          "<td>" + esc(r.category) + "</td>" +
          "<td>" + esc(r.chains.slice(0, 2).join(", ")) + (r.chains.length > 2 ? " +" + (r.chains.length - 2) : "") + "</td>" +
          '<td class="num">' + fmtMoney(r.tvlUsd) + "</td>" +
          '<td class="num ' + (r.tvlGrowth7d >= 0 ? "pos" : "neg") + '">' + fmtPct(r.tvlGrowth7d) + "</td>" +
          '<td class="num">' + fmtMoney(r.impliedFdvUsd) + "</td>" +
          '<td class="num">' + Math.round(r.launchProbability * 100) + "%</td>" +
          '<td><span class="scorebar ' + barCls + '"><i style="width:' + r.radarScore + '%"></i></span>' + r.radarScore + "</td>" +
          '<td class="num">' + fmtMoney(r.farmerEvUsd) + "</td>" +
          '<td><span class="verdict ' + verdictClass(r.verdict) + '">' + r.verdict + "</span></td>";
        tr.addEventListener("click", function () { openDetail(r.slug); });
        tb.appendChild(tr);
      });
    }

    function openDetail(slug) {
      var r = rows.find(function (x) { return x.slug === slug; });
      if (!r) return;
      activeSlug = slug;
      var growthFactor = 1 + 0.25 * Math.max(-0.5, Math.min(2, r.tvlGrowth7d));
      var maturityFactor = 0.6 + (0.4 * Math.min(r.ageMonths, 24)) / 24;
      $("d-name").textContent = "#" + r.rank + " · " + r.name;
      $("d-sub").textContent =
        r.category + " · " + r.chains.join(", ") + " · " + r.ageMonths + " months old" +
        (r.points ? " · " + (r.pointsProgram || "points program") : " · no points program") +
        (r.raisedUsdM ? " · $" + r.raisedUsdM + "M raised" : "");
      $("d-metrics").innerHTML = [
        ["TVL", fmtMoney(r.tvlUsd), "7d " + fmtPct(r.tvlGrowth7d)],
        ["Implied FDV", fmtMoney(r.impliedFdvUsd), r.categoryMultiple + "× peer multiple"],
        ["Launch odds", Math.round(r.launchProbability * 100) + "%", "logistic prior"],
        ["Radar score", String(r.radarScore) + " / 100", r.verdict],
        ["Farmer EV", fmtMoney(r.farmerEvUsd), "5% of FDV × odds"],
        ["Farm cost", "~$" + r.farmCostUsd, "~" + r.farmTimeMinPerWeek + " min / week"],
      ].map(function (m) {
        return '<div class="metric"><div class="k">' + m[0] + '</div><div class="v">' + esc(m[1]) +
          '</div><div class="s">' + esc(m[2]) + "</div></div>";
      }).join("");
      $("d-math").innerHTML =
        "<div><span>TVL</span><span>" + fmtMoney(r.tvlUsd) + "</span></div>" +
        "<div><span>× " + esc(r.category) + " peer multiple</span><span>" + r.categoryMultiple + "×</span></div>" +
        "<div><span>× growth factor (7d " + fmtPct(r.tvlGrowth7d) + ")</span><span>" + growthFactor.toFixed(2) + "×</span></div>" +
        "<div><span>× maturity factor (" + r.ageMonths + " mo)</span><span>" + maturityFactor.toFixed(2) + "×</span></div>" +
        '<div class="total"><span>Implied FDV</span><span>' + fmtMoney(r.impliedFdvUsd) + "</span></div>" +
        "<div><span>Peers priced from</span><span>" + esc(r.compsUsed.join(", ") || "global median") + "</span></div>";
      $("d-risks").innerHTML = r.risks.map(function (x) { return "<li>" + esc(x) + "</li>"; }).join("");
      $("d-farm-cost").textContent = "· ~$" + r.farmCostUsd + " total · ~" + r.farmTimeMinPerWeek + " min/week";
      $("d-farm").innerHTML = r.farmPlan.map(function (s) {
        return "<li><strong>" + esc(s.action) + "</strong><br><span class='muted small'>" + esc(s.detail) +
          "</span><br><span class='cost'>~$" + s.estCostUsd + " · " + esc(s.cadence) + "</span></li>";
      }).join("");
      $("d-defillama").textContent = "DefiLlama record: defillama.com/protocol/" + r.slug;
      $("detail").hidden = false;
      document.querySelectorAll("#board-body tr").forEach(function (tr) { tr.classList.remove("active"); });
      var trEl = document.querySelector('#board-body tr[data-slug="' + slug + '"]');
      if (trEl) trEl.classList.add("active");
      history.replaceState(null, "", "#protocol=" + encodeURIComponent(slug));
      $("detail").scrollIntoView({ behavior: "smooth", block: "nearest" });
    }

    function closeDetail() {
      activeSlug = null;
      $("detail").hidden = true;
      history.replaceState(null, "", location.pathname + location.search);
      document.querySelectorAll("#board-body tr").forEach(function (tr) { tr.classList.remove("active"); });
    }

    function resetFilters() {
      $("q").value = ""; $("cat").value = ""; $("chain").value = "";
      $("sort").value = "fdv"; $("points-only").checked = false; $("prime-only").checked = false;
      applyFilters();
    }

    ["q", "cat", "chain", "sort", "points-only", "prime-only"].forEach(function (id) {
      $(id).addEventListener("input", applyFilters);
      $(id).addEventListener("change", applyFilters);
    });
    $("reset").addEventListener("click", resetFilters);
    $("empty-reset").addEventListener("click", resetFilters);
    $("d-close").addEventListener("click", closeDetail);

    // ---- hash routing: filtered view / detail view ----
    var h = stateFromHash();
    if (h.cat) $("cat").value = h.cat;
    if (h.chain) $("chain").value = h.chain;
    if (h.q) $("q").value = h.q;
    if (h.sort) $("sort").value = h.sort; else $("sort").value = "fdv";
    applyFilters();
    if (h.protocol) openDetail(h.protocol);
  }

  function renderTop10(top) {
    var max = Math.max.apply(null, top.map(function (r) { return r.radarScore; }));
    var W = 340, rowH = 24, labelW = 92;
    var svg = '<svg viewBox="0 0 ' + W + " " + top.length * rowH + '" role="presentation">';
    top.forEach(function (r, i) {
      var y = i * rowH + 4;
      var w = Math.max(4, ((W - labelW - 44) * r.radarScore) / max);
      svg += '<text class="lbl" x="0" y="' + (y + 11) + '">' + esc(r.name.slice(0, 13)) + "</text>";
      svg += '<rect class="bar" x="' + labelW + '" y="' + y + '" width="' + w.toFixed(1) + '" height="13" rx="3"/>';
      svg += '<text class="val" x="' + (labelW + w + 6) + '" y="' + (y + 11) + '">' + r.radarScore + "</text>";
    });
    $("chart-top10").innerHTML = svg + "</svg>";
  }

  function renderMultiples(multiples) {
    var entries = Object.entries(multiples).sort(function (a, b) { return b[1] - a[1]; });
    var max = Math.max.apply(null, entries.map(function (e) { return e[1]; }));
    var W = 340, rowH = 24, labelW = 92;
    var svg = '<svg viewBox="0 0 ' + W + " " + entries.length * rowH + '" role="presentation">';
    entries.forEach(function (e, i) {
      var y = i * rowH + 4;
      var w = Math.max(4, ((W - labelW - 44) * e[1]) / max);
      svg += '<text class="lbl" x="0" y="' + (y + 11) + '">' + esc(e[0].slice(0, 13)) + "</text>";
      svg += '<rect class="bar2" x="' + labelW + '" y="' + y + '" width="' + w.toFixed(1) + '" height="13" rx="3"/>';
      svg += '<text class="val" x="' + (labelW + w + 6) + '" y="' + (y + 11) + '">' + e[1].toFixed(1) + "×</text>";
    });
    $("chart-multiples").innerHTML = svg + "</svg>";
  }

  function renderScatter(rows) {
    var W = 340, H = 240, pad = 34;
    var xs = rows.map(function (r) { return Math.log10(Math.max(r.tvlUsd, 1)); });
    var ys = rows.map(function (r) { return Math.log10(Math.max(r.impliedFdvUsd, 1)); });
    var x0 = Math.floor(Math.min.apply(null, xs)), x1 = Math.ceil(Math.max.apply(null, xs));
    var y0 = Math.floor(Math.min.apply(null, ys)), y1 = Math.ceil(Math.max.apply(null, ys));
    var X = function (v) { return pad + ((v - x0) / (x1 - x0)) * (W - 2 * pad); };
    var Y = function (v) { return H - pad - ((v - y0) / (y1 - y0)) * (H - 2 * pad); };
    var svg = '<svg viewBox="0 0 ' + W + " " + H + '" role="presentation">';
    for (var gx = x0; gx <= x1; gx++) {
      svg += '<line class="grid-line" x1="' + X(gx) + '" y1="' + (H - pad) + '" x2="' + X(gx) + '" y2="8"/>';
      svg += '<text class="lbl" x="' + X(gx) + '" y="' + (H - 18) + '" text-anchor="middle">10^' + gx + "</text>";
    }
    for (var gy = y0; gy <= y1; gy++) {
      svg += '<line class="grid-line" x1="' + pad + '" y1="' + Y(gy) + '" x2="' + (W - pad) + '" y2="' + Y(gy) + '"/>';
      svg += '<text class="lbl" x="8" y="' + (Y(gy) + 4) + '">10^' + gy + "</text>";
    }
    rows.forEach(function (r) {
      var cx = X(Math.log10(Math.max(r.tvlUsd, 1)));
      var cy = Y(Math.log10(Math.max(r.impliedFdvUsd, 1)));
      var rad = 2.5 + r.launchProbability * 5;
      var color = r.verdict === "PRIME" ? "#2ee6a8" : r.verdict === "WATCH" ? "#ffd166" : "#8b98b8";
      svg += '<circle cx="' + cx.toFixed(1) + '" cy="' + cy.toFixed(1) + '" r="' + rad.toFixed(1) +
        '" fill="' + color + '" opacity="0.8"><title>' + esc(r.name) + ": TVL " + fmtMoney(r.tvlUsd) +
        ", FDV " + fmtMoney(r.impliedFdvUsd) + "</title></circle>";
    });
    svg += '<text class="lbl" x="' + W / 2 + '" y="' + (H - 4) + '" text-anchor="middle">TVL (USD, log)</text>';
    $("chart-scatter").innerHTML = svg + "</svg>";
  }

  loadBoard()
    .then(main)
    .catch(function (err) {
      $("provenance-text").textContent = "Could not load board data: " + err.message +
        ". Run node main.ts to regenerate the output, then open the dashboard from the output folder.";
      console.error(err);
    });
})();
